<?php require_once __DIR__ . '/../includes/functions.php'; if (logged_in()) redirect(dashboard_path());
if ($_SERVER['REQUEST_METHOD'] === 'POST') { verify_csrf(); $username = trim($_POST['username'] ?? ''); $password = $_POST['password'] ?? ''; $q = db()->prepare('SELECT u.*, m.id mahasiswa_id, d.id dosen_id FROM users u LEFT JOIN mahasiswa m ON m.user_id=u.id LEFT JOIN dosen d ON d.user_id=u.id WHERE u.username=? AND u.is_active=1 LIMIT 1'); $q->execute([$username]); $account=$q->fetch(); if ($account && password_verify($password, $account['password'])) { session_regenerate_id(true); $_SESSION['user']=['id'=>$account['id'],'username'=>$account['username'],'role'=>$account['role'],'mahasiswa_id'=>$account['mahasiswa_id'],'dosen_id'=>$account['dosen_id']]; $_SESSION['last_activity']=time(); redirect(dashboard_path()); } flash('error','Username atau password tidak sesuai.'); }
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login SIAKAD</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet"><link href="<?= url('assets/css/app.css') ?>" rel="stylesheet"></head><body class="d-flex align-items-center min-vh-100"><div class="container"><div class="row justify-content-center"><div class="col-md-5 col-lg-4"><div class="card p-4"><div class="text-center mb-4"><i class="bi bi-mortarboard-fill text-primary fs-1"></i><h3 class="fw-bold">SIAKAD</h3><p class="text-secondary">Sistem Informasi Akademik</p></div><?php if($m=flash('error')):?><div class="alert alert-danger"><?=e($m)?></div><?php endif;?><?php if(isset($_GET['timeout'])):?><div class="alert alert-warning">Sesi Anda telah berakhir.</div><?php endif;?><form method="post"><?=csrf_field()?><div class="mb-3"><label class="form-label">Username</label><input required autofocus class="form-control" name="username"></div><div class="mb-4"><label class="form-label">Password</label><input required class="form-control" type="password" name="password"></div><button class="btn btn-primary w-100">Masuk <i class="bi bi-arrow-right"></i></button></form></div></div></div></div></body></html>
